 "content": "from collections import deque


def transform(grid):
    """For each enclosed zero pocket, mark its inner edge and bounding frame."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    pockets = []

    # Four-connected background closure matches the orthogonal wall contour.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            pocket = set()
            reaches_edge = False
            while q:
                x, y = q.popleft()
                pocket.add((x, y))
                reaches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not reaches_edge:
                pockets.append(pocket)

    for pocket in pockets:
        wall = set()
        for r, c in pocket:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    wall.add((nr, nc))
        if not wall:
            continue

        # The cavity edge is the set of pocket cells Moore-adjacent to its wall.
        for r, c in pocket:
            if any((r + dr, c + dc) in wall
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3

        # A one-cell rectangular 2-frame surrounds the wall's bounding box.
        r0 = max(0, min(r for r, _ in wall) - 1)
        r1 = min(h - 1, max(r for r, _ in wall) + 1)
        c0 = max(0, min(c for _, c in wall) - 1)
        c1 = min(w - 1, max(c for _, c in wall) + 1)
        for c in range(c0, c1 + 1):
            for r in (r0, r1):
                if grid[r][c] == 0 and (r, c) not in pocket:
                    out[r][c] = 2
        for r in range(r0, r1 + 1):
            for c in (c0, c1):
                if grid[r][c] == 0 and (r, c) not in pocket:
                    out[r][c] = 2
    return out


