def transform(grid):
    """For each enclosed zero region, color its inner rim 3 and outside halo 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    regions = []

    # Orthogonal background connectivity: any zero component reaching an edge
    # is exterior; enclosed pockets are the regions bounded by 1-strokes.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            edge = False
            while q:
                x, y = q.popleft()
                cells.add((x, y))
                edge |= x in (0, h - 1) or y in (0, w - 1)
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not edge:
                regions.append(cells)

    all_regions = set().union(*regions) if regions else set()
    for region in regions:
        wall = set()
        for r, c in region:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    wall.add((nr, nc))
        if not wall:
            continue
        # Inner zero cells adjacent to the contour are recolored 3.
        for r, c in region:
            if any((r + dr, c + dc) in wall
                   for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc):
                out[r][c] = 3
        # Exterior halo is the one-cell 8-neighborhood of that contour.
        for r, c in wall:
            for nr in range(max(0, r - 1), min(h, r + 2)):
                for nc in range(max(0, c - 1), min(w, c + 2)):
                    if grid[nr][nc] == 0 and (nr, nc) not in all_regions:
                        out[nr][nc] = 2
    return out


