def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    cavities = []

    # Enclosed background regions are bounded by orthogonally connected 1-lines.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            region = set()
            touches_edge = False
            while q:
                x, y = q.popleft()
                region.add((x, y))
                touches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if not touches_edge:
                cavities.append(region)

    for region in cavities:
        wall = set()
        inner_edge = set()
        for r, c in region:
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    wall.add((nr, nc))
                    inner_edge.add((r, c))
        if not wall:
            continue

        for r, c in inner_edge:
            out[r][c] = 3

        # Draw a rectangular one-cell frame outside the complete contour bounds.
        top = max(0, min(r for r, _ in wall) - 1)
        bottom = min(h - 1, max(r for r, _ in wall) + 1)
        left = max(0, min(c for _, c in wall) - 1)
        right = min(w - 1, max(c for _, c in wall) + 1)
        for c in range(left, right + 1):
            for r in (top, bottom):
                if grid[r][c] == 0:
                    out[r][c] = 2
        for r in range(top, bottom + 1):
            for c in (left, right):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out


